  "scope_issues": [],
  "statuses": [
    {
      "evidence_quote": "I run a small, independent charity which attempts to help people struggling with their vet costs. I have several people who pay monthly by direct debit and also receive some one off donations.",
      "id": "a1",
      "justification": "The customer runs a charity and has individual donors making donations, satisfying the condition that the donor is an individual who made a donation to a recognised charity or CASC.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "Her tax summary for the year to 5 April 2026 shows £980 of Income Tax paid. Her signed note lists £200 of other Gift Aid donations that year; the treasurer’s sheet shows £30 recoverable on this £120 and £50 on the others, £80 in total, well below her £980.",
      "id": "a2",
      "justification": "The donor has paid £980 in Income Tax in the tax year, which exceeds the total Gift Aid claimed (£80), satisfying the requirement that the donor has paid at least as much in Income Tax or Capital Gains Tax as the amount of Gift Aid claimed.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "Elaine signed an electronic Gift Aid declaration on 15 March, and the e-signature service holds the signed document, timestamp and audit record. The declaration says it covers this donation, and the finance assistant matched it to FP-0316-EL through her donor record.",
      "id": "a3",
      "justification": "The donor has made a Gift Aid declaration that explicitly covers this donation, as confirmed by the signed electronic declaration and audit record.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "It did not go through a payroll giving scheme, and no shares, securities or other assets were delivered. An older spreadsheet groups it with two CAF card and voucher redemptions (CC-0314, VC-0317), but those were paid to the charity in a combined batch on 18 March, while FP-0316-EL came directly from Elaine’s bank on 16 March.",
      "id": "a4",
      "justification": "The donation was made directly via Elaine’s bank app, not through a payroll giving scheme, satisfying the condition that it is not made through Payroll Giving.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "The sales, booking and event records show nothing linked to this payment, and the only thing sent to Elaine was the standard thank-you email; she was not offered admission, advertising, a product or any other benefit.",
      "id": "a5",
      "justification": "There is no evidence of a payment for goods or services or a transaction arising from the charity buying goods and services; the donation was made for a vet cost relief and no benefit was provided beyond a standard thank-you email.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "she sent the £120 from her banking app after reading about a rescued dog’s emergency treatment. The only thing sent to Elaine was the standard thank-you email; she was not offered admission, advertising, a product or any other benefit.",
      "id": "a6",
      "justification": "The donation was not made in exchange for a benefit over a certain limit; the donor received only a standard thank-you email, with no tangible benefit or service offered.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "It did not go through a payroll giving scheme, and no shares, securities or other assets were delivered.",
      "id": "a7",
      "justification": "The donation was not of shares or other securities, as no such assets were delivered or involved in the transaction.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "An older spreadsheet groups it with two CAF card and voucher redemptions (CC-0314, VC-0317), but those were paid to the charity in a combined batch on 18 March, while FP-0316-EL came directly from Elaine’s bank on 16 March.",
      "id": "a8",
      "justification": "The donation FP-0316-EL came directly from Elaine’s bank, not from a charity card or voucher. The grouping with CAF redemptions is a separate batch and does not indicate the donation originated from a card or voucher.",
      "status": "TRUE"
    }
  ]
}
